package com.medtrack.medicine.repository; import com.medtrack.medicine.entity.Medicine; import java.util.*; import org.springframework.data.jpa.repository.*; public interface MedicineRepository extends JpaRepository<Medicine,UUID>{boolean existsBySku(String sku); @Query("select m from Medicine m where lower(m.sku) like lower(concat('%',:query,'%')) or lower(m.genericName) like lower(concat('%',:query,'%'))") org.springframework.data.domain.Page<Medicine> search(String query,org.springframework.data.domain.Pageable pageable);}
